namespace ToneCustoms.ShellStudio.Export;
public sealed class ResourceValidationService { public IReadOnlyList<string> ValidateFolder(string root){var r=new List<string>();if(!File.Exists(Path.Combine(root,"fxmanifest.lua")))r.Add("fxmanifest.lua missing");var stream=Path.Combine(root,"stream");if(!Directory.Exists(stream))r.Add("stream folder missing");else r.AddRange(new GtaOutputVerifier().Verify(stream));return r;} }
